1	export type Cell = [x: number, y: number];
2	
3	const isWithinOneStep = (coordinate: number, other: number): boolean =>
4	  Math.abs(coordinate - other) <= 1;
5	
6	const isSameCell = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
7	  x === otherX && y === otherY;
8	
9	const isAdjacentOrSame = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
10	  isWithinOneStep(x, otherX) && isWithinOneStep(y, otherY);
11	
12	const isNeighbor = (cell: Cell, other: Cell): boolean =>
13	  isAdjacentOrSame(cell, other) && !isSameCell(cell, other);
14	
15	const countLiveNeighbors = (cell: Cell, liveCells: Cell[]): number =>
16	  liveCells.filter((other) => isNeighbor(cell, other)).length;
17	
18	const neighborsOf = ([x, y]: Cell): Cell[] =>
19	  [-1, 0, 1].flatMap((dx) =>
20	    [-1, 0, 1]
21	      .filter((dy) => !(dx === 0 && dy === 0))
22	      .map((dy): Cell => [x + dx, y + dy]),
23	  );
24	
25	const isLive = (cell: Cell, liveCells: Cell[]): boolean =>
26	  liveCells.some((liveCell) => isSameCell(cell, liveCell));
27	
28	const withoutDuplicates = (cells: Cell[]): Cell[] =>
29	  cells.filter(
30	    (cell, index) =>
31	      index === cells.findIndex((other) => isSameCell(cell, other)),
32	  );
33	
34	const isLiveNextGeneration = (cell: Cell, liveCells: Cell[]): boolean => {
35	  const liveNeighbors = countLiveNeighbors(cell, liveCells);
36	  return liveNeighbors === 3 || (liveNeighbors === 2 && isLive(cell, liveCells));
37	};
38	
39	const cellsThatCouldChange = (liveCells: Cell[]): Cell[] =>
40	  withoutDuplicates(liveCells.flatMap((cell) => [cell, ...neighborsOf(cell)]));
41	
42	export const nextGeneration = (liveCells: Cell[]): Cell[] =>
43	  cellsThatCouldChange(liveCells).filter((cell) =>
44	    isLiveNextGeneration(cell, liveCells),
45	  );
